        master=add(new StyledButton(MASTER,left,ty,fullW,toggleH,Lang.s("Автовозврат Baritone","Baritone auto return","Автоповернення Baritone","Baritone-Auto-Rückkehr","Auto-powrót Baritone")).asToggle(config.isAutoReturnEnabled()).tip(Lang.s("§fВозврат в точку старта","§fReturn to the start point","§fПовернення в точку старту","§fRückkehr zum Startpunkt","§fPowrót do punktu startu"),Lang.s("§7Вкл: перед повтором мод сам приведёт вас туда, где начиналась запись.","§7On: before playback the mod walks you back to where the recording started.","§7Увімк: перед повтором мод сам приведе вас туди, де починався запис.","§7An: vor der Wiedergabe bringt die Mod dich dorthin zurück, wo die Aufnahme begann.","§7Wł: przed powtórką mod sam zaprowadzi cię tam, gdzie zaczęło się nagranie."),Lang.s("§7Выкл: повтор начнётся там, где вы стоите сейчас.","§7Off: playback starts where you stand right now.","§7Вимк: повтор почнеться там, де ви стоїте зараз.","§7Aus: die Wiedergabe startet dort, wo du gerade stehst.","§7Wył: powtórka zacznie się tam, gdzie teraz stoisz."),Lang.s("§8Нужен мод Baritone. Если дойти не выйдет, мод покажет метку и попросит встать на неё.","§8Requires Baritone. If it cannot walk there, the mod shows a marker and asks you to stand on it.","§8Потрібен мод Baritone. Якщо дійти не вийде, мод покаже мітку й попросить встати на неї.","§8Benötigt Baritone. Wenn es nicht hinkommt, zeigt die Mod eine Markierung und bittet dich, dich daraufzustellen.","§8Wymaga moda Baritone. Jeśli nie uda się dojść, mod pokaże znacznik i poprosi, by na nim stanąć.")));ty+=toggleH+5;
        cursor=dep(new StyledButton(CURSOR,left,ty,fullW,toggleH,Lang.s("Вернуть взгляд к первому кадру","Restore the view to the first frame","Повернути погляд до першого кадру","Blick auf den ersten Frame zurücksetzen","Przywróć wzrok do pierwszej klatki")).asToggle(config.isCursorStabilization()).tip(Lang.s("§fВзгляд как в начале записи","§fView as at the recording start","§fПогляд як на початку запису","§fBlick wie am Aufnahmebeginn","§fWzrok jak na początku nagrania"),Lang.s("§7Перед стартом камера один раз повернётся туда же, куда вы смотрели в начале записи.","§7Before the start the camera turns once to where you looked at the beginning of the recording.","§7Перед стартом камера один раз повернеться туди ж, куди ви дивилися на початку запису.","§7Vor dem Start dreht sich die Kamera einmal dorthin, wo du zu Beginn der Aufnahme hingeschaut hast.","§7Przed startem kamera raz obróci się tam, gdzie patrzyłeś na początku nagrania."),Lang.s("§7Работает и с возвратом, и без него.","§7Works both with and without the auto return.","§7Працює і з поверненням, і без нього.","§7Funktioniert mit und ohne Auto-Rückkehr.","§7Działa zarówno z powrotem, jak i bez niego."),Lang.s("§8Потом обзором управляете вы.","§8After that you control the view.","§8Потім оглядом керуєте ви.","§8Danach steuerst du die Sicht.","§8Potem widokiem sterujesz ty.")));ty+=toggleH+5;
