        paramTop=ty+11;rowH=18;int fy=y+h-26;paramStep=Math.max(19,Math.min(24,(fy-6-paramTop-rowH)/2));int step=paramStep;
        addStepper(POS_DEC,POS_INC,paramTop,Lang.s("Точность возврата","Return accuracy","Точність повернення","Rückkehr-Genauigkeit","Dokładność powrotu"),Lang.s("§7Насколько близко к точке старта нужно встать: 0.05-0.50 блока.","§7How close to the start point you must stand: 0.05-0.50 blocks.","§7Наскільки близько до точки старту треба встати: 0.05-0.50 блока.","§7Wie nah du am Startpunkt stehen musst: 0.05-0.50 Blöcke.","§7Jak blisko punktu startu musisz stanąć: 0.05-0.50 bloku."));addStepper(SPEED_DEC,SPEED_INC,paramTop+step,Lang.s("Скорость подхода","Approach speed","Швидкість підходу","Annäherungsgeschwindigkeit","Prędkość podejścia"),Lang.s("§7Как быстро идти на последних шагах: 0.2-1.0.","§7How fast to walk on the last steps: 0.2-1.0.","§7Як швидко йти на останніх кроках: 0.2-1.0.","§7Wie schnell auf den letzten Schritten gegangen wird: 0.2-1.0.","§7Jak szybko iść na ostatnich krokach: 0.2-1.0."));addStepper(TIME_DEC,TIME_INC,paramTop+step*2,Lang.s("Сколько ждать","How long to wait","Скільки чекати","Wie lange warten","Ile czekać"),Lang.s("§7Если дойти не вышло, мод бросит попытку: 15-180 сек.","§7If it cannot get there, the mod gives up: 15-180 sec.","§7Якщо дійти не вдалося, мод кине спробу: 15-180 сек.","§7Wenn es nicht hinkommt, gibt die Mod auf: 15-180 Sek.","§7Jeśli nie uda się dojść, mod przerwie próbę: 15-180 s."));
