    private static float snap2(float v){return Math.round(v*100f)/100f;}private static float snap1(float v){return Math.round(v*10f)/10f;}
    private void sync(){master.setOn(config.isAutoReturnEnabled());cursor.setOn(config.isCursorStabilization());skip.setOn(config.isSkipLoopStartDelay());}
    @Override public void drawScreen(int mx,int my,float pt){{int bd=UiTheme.GLASS_BACKDROP;drawGradientRect(0,0,width,height,bd,bd);}UiTheme.window(x,y,x+w,y+h,30);int hx=x+14,hy=y+11;Gui.drawRect(hx,hy,hx+3,hy+10,UiTheme.ACCENT);UiTheme.drawFitted(fontRenderer,Lang.s("§lСтабилизация и автовозврат","§lStabilization and auto return","§lСтабілізація і автоповернення","§lStabilisierung und Auto-Rückkehr","§lStabilizacja i auto-powrót"),hx+9,hy,w-40,UiTheme.TEXT);UiTheme.sectionLabel(fontRenderer,Lang.s("ПОВЕДЕНИЕ","BEHAVIOR","ПОВЕДІНКА","VERHALTEN","ZACHOWANIE"),x+16,y+36,w-32);UiTheme.sectionLabel(fontRenderer,Lang.s("ДОВОДКА BARITONE","BARITONE APPROACH","ДОВЕДЕННЯ BARITONE","BARITONE-ANNÄHERUNG","DOPROWADZANIE BARITONE"),x+16,paramTop-12,w-32);String[] names={Lang.s("Точность позиции","Position accuracy","Точність позиції","Positionsgenauigkeit","Dokładność pozycji"),Lang.s("Скорость доводки","Approach speed","Швидкість доведення","Annäherungstempo","Prędkość doprowadzania"),Lang.s("Тайм-аут","Timeout","Тайм-аут","Timeout","Limit czasu")};String[] values={String.format(java.util.Locale.ROOT,"%.2f",config.getReturnPositionTolerance()),String.format(java.util.Locale.ROOT,"%.1f",config.getReturnAlignSpeed()),config.getReturnTimeoutSeconds()+Lang.s("с","s","с","s","s")};int step=paramStep,chip=58,bw=22,gap=4,right=x+w-16,chipX=right-bw-gap-chip;for(int i=0;i<3;i++){int ry=paramTop+step*i;UiTheme.drawFitted(fontRenderer,names[i],x+18,ry+5,Math.max(20,chipX-x-24),UiTheme.TEXT_DIM);UiTheme.inset(chipX,ry,chipX+chip,ry+rowH);UiTheme.drawCenteredFitted(fontRenderer,values[i],chipX+chip/2f,ry+5,chip-6,UiTheme.TEXT,false);}if(y+h-40>=paramTop+step*2+rowH+2)fontRenderer.drawString(changed()?Lang.s("§eЕсть несохранённые изменения","§eUnsaved changes","§eЄ незбережені зміни","§eUngespeicherte Änderungen","§eSą niezapisane zmiany"):Lang.s("§8Esc: отмена","§8Esc: cancel","§8Esc: скасувати","§8Esc: abbrechen","§8Esc: anuluj"),x+16,y+h-40,UiTheme.TEXT_MUTE);sync();super.drawScreen(mx,my,pt);for(GuiButton raw:buttonList)if(raw instanceof StyledButton){StyledButton b=(StyledButton)raw;if(b.visible&&b.isMouseOver()&&b.tooltip!=null){if(UiTheme.tipReady(b))UiTheme.tooltip(fontRenderer,b.tooltip,mx,my,width,height);break;}}}
    @Override protected void actionPerformed(GuiButton b)throws IOException{switch(b.id){case MASTER:config.setAutoReturnEnabled(!config.isAutoReturnEnabled());break;case CURSOR:config.setCursorStabilization(!config.isCursorStabilization());break;case SKIP_DELAY:config.setSkipLoopStartDelay(!config.isSkipLoopStartDelay());break;case POS_DEC:config.setReturnPositionTolerance(snap2(config.getReturnPositionTolerance()-0.01f));break;case POS_INC:config.setReturnPositionTolerance(snap2(config.getReturnPositionTolerance()+0.01f));break;case SPEED_DEC:config.setReturnAlignSpeed(snap1(config.getReturnAlignSpeed()-0.1f));break;case SPEED_INC:config.setReturnAlignSpeed(snap1(config.getReturnAlignSpeed()+0.1f));break;case TIME_DEC:config.setReturnTimeoutSeconds(config.getReturnTimeoutSeconds()-15);break;case TIME_INC:config.setReturnTimeoutSeconds(config.getReturnTimeoutSeconds()+15);break;case SAVE:saved=true;snapshot();mc.displayGuiScreen(parent);break;case CANCEL:restore();mc.displayGuiScreen(parent);break;}sync();}
    @Override protected void keyTyped(char c,int key)throws IOException{if(key==1){restore();mc.displayGuiScreen(parent);}else super.keyTyped(c,key);}
    @Override public void onGuiClosed(){if(!saved)restore();}
    @Override public boolean doesGuiPauseGame(){return false;}
